"""Unit 16: Tagalog Basic Course, Semester I, Unit 4, Chapter 4, Lesson 3: At the Store.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, September 2017).
Pictures, audio, partner work, role plays and the web links are left out; the book's answer keys are used
(misprints noted), prices are written in words in the spoken lines and with the peso sign in English notes."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


